"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3593],{25035:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"EnergyCannonConfig","desc":"Tuning for the train-mounted Energy Cannon (single heat-driven laser, hold-to-fire).\\nShared by the server, the client controller and `EnergyCannonMath`. Heat runs 0..1;\\nbeam width and damage grow with heat up to `PeakHeat`, and reaching 1 overheats the\\ncannon until it has cooled to 0. All sound keys resolve through SoundManager/SoundConfig.\\nAngles here are in degrees unless the name says otherwise.","source":{"line":11,"path":"src/ReplicatedStorage/SharedModules/Configs/EnergyCannonConfig.luau"}}')}}]);